const ans=[
{question_id:"sq:deviations:participants-aware",answer:"yes",justification:"Although the paper calls the trial single-blind and says participants were blinded (p. 3), the assigned arms involved visibly distinguishable conduct: supervised, real-time video telerehabilitation; unsupervised home exercise with daily calls; and usual care (pp. 4–5). Participants would know which they received. The explicit blinding assertion is a material counterpoint but does not plausibly conceal these different intervention experiences.",unknowns:[],bases:[{evidence:["eh_6a3a61395c2666c3","eh_0815ad60e1dc1f4e"],role:"indirect_support"}],absence_searches:[],limitations:[],counterevidence:[{evidence:["eh_6a3a61395c2666c3"],implication:"Authors explicitly state participants were blinded, contrary to likely awareness from the distinct intervention experiences."}]},
{question_id:"sq:deviations:personnel-aware",answer:"yes",justification:"A therapist supervised PT by two-way video and provided real-time feedback; the education arm received daily therapist calls, while control received usual care (pp. 4–5). Delivery personnel necessarily knew the intervention they were delivering; the paper's blinding statement appears to refer to participants and assessors, not carers/providers.",unknowns:[],bases:[{evidence:["eh_0815ad60e1dc1f4e","eh_6a3a61395c2666c3"],role:"indirect_support"}],absence_searches:[],limitations:[],counterevidence:[{evidence:["eh_6a3a61395c2666c3"],implication:"The report calls participants and assessors blinded; it does not claim intervention providers were blinded."}]},
{question_id:"sq:deviations:context-deviations",answer:"probably_no",justification:"The report notes two participants discontinued because of high intensity (p. 11), a change potentially inconsistent with completing the 30-session protocol (pp. 4, 12). It does not indicate that recruitment, research-only engagement, or trial personnel caused their discontinuation; treatment burden is compatible with ordinary non-adherence. Other attrition reasons include surgery cancellation and a fall, but no trial-context cause is reported. Thus no affirmative context-caused deviation is established; cause and protocol status remain uncertain.",unknowns:["Whether stopping because of high intensity violated protocol and whether any trial-specific engagement or personnel decision caused it.","Whether surgery cancellations or the fall were context-caused."],bases:[{evidence:["eh_6cc2e1f4d915b54c","eh_3c87e963806cb79d"],role:"indirect_support"}],absence_searches:[],limitations:[{premise:"Trial-context causation of the reported non-completion/attrition.",stopping_rationale:"Main report gives reasons for some losses but does not link them to recruitment, research-only engagement, or trial personnel; no protocol/SAP was available among the captured report pages to resolve this."}],counterevidence:[]},
{question_id:"sq:deviations:appropriate-analysis",answer:"no",justification:"The approved estimand is effect of assignment among all randomized participants. Sixty were randomized (20/group), but only 53 were analyzed (18, 17, 18). The flow diagram records seven post-randomization losses/exclusions, including two intervention discontinuations, two surgery cancellations, and a fall; the main report describes repeated-measures ANOVA but does not show that all randomized participants were analyzed by assignment or that exclusions were limited to participants with missing outcome data. Excluding eligible randomized participants for reasons beyond missing outcomes is not an appropriate assignment analysis.",unknowns:["For each excluded participant, whether the approved strength outcomes were missing or observed and the precise analysis grouping/exclusion rule.","Whether the surgery-cancelled participants remained eligible for the assignment estimand."],bases:[{evidence:["eh_3c87e963806cb79d","eh_bec13ad1486a4b6a","eh_f628fda610788e52"],role:"direct_support"}],absence_searches:[],limitations:[{premise:"Whether excluded participants had missing versus observed outcome data, and actual analysis grouping.",stopping_rationale:"The report supplies randomized/analyzed counts, flow reasons, and the ANOVA approach, but no participant-level outcome availability or assignment-group analysis rule."}],counterevidence:[]},
{question_id:"sq:deviations:substantial-impact",answer:"probably_yes",justification:"Seven of 60 randomized participants (about 12%) were not analyzed. This is not a trivial fraction and could substantially affect the time-by-group estimate, particularly because causes include intervention discontinuation, surgery cancellation, and a fall rather than a documented missing-outcome-only mITT rule. The report provides no prognostic comparison or sensitivity analysis; therefore potential impact is probable, not certain.",unknowns:["Whether the excluded participants' strength outcomes or prognoses differed materially from those analyzed."],bases:[{evidence:["eh_3c87e963806cb79d"],role:"indirect_support"}],absence_searches:[],limitations:[{premise:"Magnitude/direction of effect of excluded participants on the reported result.",stopping_rationale:"No outcome values, prognostic comparisons, or sensitivity analyses for excluded participants are reported."}],counterevidence:[]}
];
